offcanvas_menu.css_offcanvas:
.el-offcanvas {
  position: fixed;
  top: 0; bottom: 0; right: 0;
  width: 320px;
  background-color: var(--el-sidebar-bg);
  border-left: 1px solid var(--el-border);
  box-shadow: -4px 0 24px rgba(0,0,0,0.05);
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 1060;
  overflow-y: auto;
}
.el-offcanvas.active { transform: translateX(0); }

offcanvas_menu.css_overlay:
.el-offcanvas-overlay {
  position: fixed;
  top: 0; left: 0; width: 100%; height: 100%;
  background-color: rgba(15, 23, 42, 0.4);
  backdrop-filter: blur(4px);
  z-index: 1050;
  display: none;
}
.el-offcanvas-overlay.active { display: block; }
body.menu-opened { overflow: hidden !important; }

offcanvas_menu.javascript:
const menuTrigger = document.getElementById('js-menu-trigger');
const menuClose = document.getElementById('js-menu-close');
const offcanvasOverlay = document.getElementById('js-offcanvas-overlay');
const offcanvasMenu = document.getElementById('js-offcanvas-menu');

const toggleMenu = (state) => {
  if (state) {
    offcanvasMenu.classList.add('active');
    offcanvasOverlay.classList.add('active');
    document.body.classList.add('menu-opened');
  } else {
    offcanvasMenu.classList.remove('active');
    offcanvasOverlay.classList.remove('active');
    document.body.classList.remove('menu-opened');
  }
};

menuTrigger.addEventListener('click', () => toggleMenu(true));
menuClose.addEventListener('click', () => toggleMenu(false));
offcanvasOverlay.addEventListener('click', () => toggleMenu(false));

curso_modulos_accordion.css:
.course-module {
  background: #ffffff;
  border: 1px solid var(--el-border);
  border-radius: 12px;
  margin-bottom: 1rem;
  overflow: hidden;
}
.course-module summary {
  padding: 1.25rem;
  font-weight: 700;
  cursor: pointer;
  background-color: var(--el-bg);
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  user-select: none;
}
.course-module summary::-webkit-details-marker { display: none; }
.course-module summary .summary-icon { transition: transform 0.3s ease; fill: var(--el-primary); }
.course-module[open] summary .summary-icon { transform: rotate(180deg); }
.module-content {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  border-top: 1px solid var(--el-border);
}

curso_modulos_accordion.javascript_exclusivo:
const modules = document.querySelectorAll('.course-module');
modules.forEach(module => {
  module.addEventListener('click', (e) => {
    if (e.target.tagName !== 'SUMMARY' && e.target.parentElement.tagName !== 'SUMMARY') return;
    if (!module.hasAttribute('open')) {
      modules.forEach(other => {
        if (other !== module) other.removeAttribute('open');
      });
    }
  });
});

