progress_engine.javascript_completo:
document.addEventListener('DOMContentLoaded', () => {
  const lessonLinks = document.querySelectorAll('.lesson-link');
  const progressBar = document.getElementById('course-progress-bar');
  const progressPanel = document.getElementById('js-elearning-panel');
  const resetBtn = document.getElementById('js-reset-progress');
  const completePostBtn = document.querySelector('.js-mark-complete-btn');

  const storageKeyArray = 'softload_elearning_progress';
  const storageKeyTotal = 'softload_elearning_total_lessons';

  let completedLessons = JSON.parse(localStorage.getItem(storageKeyArray)) || [];
  let totalLessons = parseInt(localStorage.getItem(storageKeyTotal)) || 0;

  if (lessonLinks.length > 0) {
    totalLessons = lessonLinks.length;
    localStorage.setItem(storageKeyTotal, totalLessons);
  }

  const renderProgressUI = () => {
    if (totalLessons === 0) return;
    if (progressPanel) progressPanel.classList.remove('d-none');

    const percentage = Math.round((completedLessons.length / totalLessons) * 100);

    if (progressBar) {
      progressBar.style.width = `${percentage}%`;
      progressBar.textContent = `${percentage}%`;
      progressBar.style.backgroundColor = percentage === 100 ? '#059669' : 'var(--el-success)';
    }

    lessonLinks.forEach(link => {
      const lessonId = link.getAttribute('data-id');
      const icon = link.querySelector('svg');
      if (completedLessons.includes(lessonId)) {
        link.classList.add('completed');
        if (icon) icon.innerHTML = '<path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/>';
      } else {
        link.classList.remove('completed');
        if (icon) icon.innerHTML = '<path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 14.5v-9l6 4.5-6 4.5z"/>';
      }
    });

    if (completePostBtn) {
      const currentPostId = completePostBtn.getAttribute('data-id');
      if (completedLessons.includes(currentPostId)) {
        completePostBtn.textContent = 'Aula já concluída';
        completePostBtn.style.opacity = '0.7';
        completePostBtn.disabled = true;
      }
    }
  };

  lessonLinks.forEach(link => {
    link.addEventListener('click', () => {
      const lessonId = link.getAttribute('data-id');
      if (!completedLessons.includes(lessonId)) {
        completedLessons.push(lessonId);
        localStorage.setItem(storageKeyArray, JSON.stringify(completedLessons));
        renderProgressUI();
      }
    });
  });

  if (completePostBtn) {
    completePostBtn.addEventListener('click', () => {
      const currentPostId = completePostBtn.getAttribute('data-id');
      if (!completedLessons.includes(currentPostId)) {
        completedLessons.push(currentPostId);
        localStorage.setItem(storageKeyArray, JSON.stringify(completedLessons));
        renderProgressUI();
        alert('Excelente! O seu progresso foi guardado.');
      }
    });
  }

  if (resetBtn) {
    resetBtn.addEventListener('click', () => {
      if (confirm('Tem a certeza de que deseja redefinir todo o progresso do curso? Esta ação não pode ser desfeita.')) {
        completedLessons = [];
        localStorage.removeItem(storageKeyArray);
        renderProgressUI();
      }
    });
  }

  renderProgressUI();
});

